function renderGeoMap(user){
  const w=el(`<div><div class="card"><div class="section-head"><div><h3>🗺️ Geo Intelligence & Inspection Map</h3><p class="muted">OpenStreetMap + Leaflet. Institute locations, live inspector location, geofence validation and routing.</p></div><span class="badge-pill badge-online">OSM</span></div><div class="map-toolbar"><div><label>Route from</label><select id="from">${state.mapInstitutes.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><div><label>Route to</label><select id="to">${state.mapInstitutes.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><button class="btn" id="routeBtn">🧭 Best route</button><button class="btn secondary" id="locBtn">📍 My location</button></div><div id="map" class="map-shell"></div><div id="mapResult" class="workflow-card" style="margin-top:10px">Select a route or use My location to validate the inspector's geofence.</div></div><div class="grid grid-2"><div class="card"><h3>Geofencing</h3><p class="muted">Use current GPS to verify that an inspection was actually performed near the assigned institute.</p><button class="btn" id="geoBtn">Check 300m geofence</button><div id="geoResult"></div></div><div class="card"><h3>Map layers</h3><div class="chips"><span>🏢 Institutes</span><span>📍 Inspector GPS</span><span>⭕ 300m geofence</span><span>🧭 OSRM route</span><span>🚨 AI risk</span></div><p class="muted" style="margin-top:10px">For production, this layer can consume official GIS/Google Earth Engine outputs without changing the inspection workflow.</p></div></div></div>`);
  setTimeout(()=>initMap(w),0); return w;
}
async function initMap(w){
  const map=L.map(w.querySelector('#map')).setView([22.5,77.5],5); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);
  const markers=[]; state.mapInstitutes.forEach(i=>{const mk=L.marker([i.lat,i.lng]).addTo(map).bindPopup(`<b>${esc(i.name)}</b><br>${esc(i.district)}<br>${esc(i.scheme)}`);markers.push(mk);});
  if(markers.length) map.fitBounds(L.featureGroup(markers).getBounds().pad(.25));
  let userMarker=null,routeLine=null;
  const getPos=()=>new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:8000}):reject(new Error('GPS not supported')));
  w.querySelector('#locBtn').onclick=async()=>{try{const p=await getPos();const lat=p.coords.latitude,lng=p.coords.longitude;if(userMarker)userMarker.remove();userMarker=L.circleMarker([lat,lng],{radius:9}).addTo(map).bindPopup('Your current GPS location').openPopup();map.setView([lat,lng],15);w.querySelector('#mapResult').textContent=`GPS captured: ${lat.toFixed(6)}, ${lng.toFixed(6)}`;}catch(e){showToast('GPS error: '+e.message,'error');}};
  w.querySelector('#routeBtn').onclick=async()=>{try{const r=await api.routeBetween({from:w.querySelector('#from').value,to:w.querySelector('#to').value});if(routeLine)routeLine.remove();routeLine=L.geoJSON(r.geometry).addTo(map);map.fitBounds(routeLine.getBounds().pad(.2));w.querySelector('#mapResult').textContent=`Best route: ${r.distanceKm} km · approx ${r.durationMin} min`;}catch(e){showToast(e.message,'error');}};
  w.querySelector('#geoBtn').onclick=async()=>{try{const p=await getPos();const r=await api.geofenceCheck({instituteId:w.querySelector('#from').value,lat:p.coords.latitude,lng:p.coords.longitude,radius:300});w.querySelector('#geoResult').innerHTML=`<div class="${r.inside?'success-box':'error-box'}">${r.inside?'✅ INSIDE':'❌ OUTSIDE'} geofence · ${r.distanceMeters}m from institute</div>`;L.circle([r.institute.lat,r.institute.lng],{radius:300}).addTo(map);}catch(e){showToast(e.message,'error');}};
}

let aiCallRuntime=null;
function renderAICall(user){
  const w=el(`<div><div class="hero ai-hero"><div><div class="eyebrow">AI VERIFICATION CALL CENTER</div><h2>AI calls the institute and asks questions</h2><p>The browser voice agent speaks the questions, captures spoken answers when supported, sends every answer to the backend and evaluates the call for compliance. Optional Twilio dialing is supported through environment variables.</p></div><span class="ai-chip">VOICE + RULE ENGINE</span></div><div class="card"><div class="grid grid-2"><div><label>Institute</label><select id="inst">${state.institutes.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><div><label>Call mode</label><select id="mode"><option value="browser">Browser AI voice (works locally)</option><option value="phone">Real phone via Twilio (requires configuration)</option></select></div></div><div class="call-question" id="question">Press Start AI Call. The agent will ask verification questions one by one.</div><div class="call-controls"><button class="btn accent" id="start">☎️ Start AI call</button><button class="btn secondary" id="speak">🔊 Speak question</button><button class="btn" id="answer">🎙️ Answer by voice</button><button class="btn secondary" id="next">Next question</button><button class="btn" id="complete">Finish & evaluate</button></div><label>Typed fallback / transcript</label><textarea id="answerText" placeholder="If microphone speech recognition is unavailable, type the caller's answer here..."></textarea><div id="callStatus" class="workflow-card">No active call.</div></div><div class="grid grid-2"><div class="card"><h3>Previous AI verification calls</h3><div id="calls"></div></div><div class="card"><h3>How the decision works</h3><div class="feature-grid"><div><b>1 · Ask</b><p>AI asks operational questions based on institute type.</p></div><div><b>2 · Listen</b><p>Speech recognition or typed fallback captures the answer.</p></div><div><b>3 · Evaluate</b><p>Answers are scored against exception rules.</p></div><div><b>4 · Escalate</b><p>High-risk answers automatically create an AI-call-triggered inspection.</p></div></div></div></div></div>`);
  const q=w.querySelector('#question'), status=w.querySelector('#callStatus'); let current=0;
  function say(text){q.textContent=text;if('speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';speechSynthesis.speak(u);}}
  function currentQuestion(){return aiCallRuntime?.call?.questions?.[current];}
  w.querySelector('#start').onclick=async()=>{try{const r=await api.startAICall({instituteId:w.querySelector('#inst').value});aiCallRuntime={call:r.call};current=0;say(r.call.questions[0].text);status.innerHTML=`<b>Call connected.</b> Target: ${esc(r.call.targetName||'Institute incharge')} · ${esc(r.call.channel)}`;if(w.querySelector('#mode').value==='phone'){try{const d=await api.dialAICall(r.call.id);status.innerHTML+=`<br>${esc(d.message||'Phone call initiated.')}`;}catch(e){status.innerHTML+=`<br>Phone mode unavailable: ${esc(e.message)}`;}}renderCalls();}catch(e){showToast(e.message,'error');}};
  w.querySelector('#speak').onclick=()=>{const qq=currentQuestion();if(qq)say(qq.text);};
  w.querySelector('#answer').onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){showToast('Speech recognition unavailable; type the answer and click Next question.','error');return;}const r=new SR();r.lang='en-IN';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{w.querySelector('#answerText').value=e.results[0][0].transcript;};r.onerror=e=>showToast('Microphone: '+e.error,'error');r.start();};
  w.querySelector('#next').onclick=async()=>{if(!aiCallRuntime?.call)return showToast('Start the AI call first','error');const qq=currentQuestion();if(!qq)return;const ans=w.querySelector('#answerText').value.trim();if(!ans)return showToast('Give an answer first','error');await api.answerAICall(aiCallRuntime.call.id,{questionId:qq.id,question:qq.text,answer:ans});aiCallRuntime.call.answers.push({questionId:qq.id,question:qq.text,answer:ans});w.querySelector('#answerText').value='';current++;if(current<aiCallRuntime.call.questions.length)say(aiCallRuntime.call.questions[current].text);else q.textContent='All questions answered. Click Finish & evaluate.';};
  w.querySelector('#complete').onclick=async()=>{if(!aiCallRuntime?.call)return showToast('Start the AI call first','error');const r=await api.completeAICall(aiCallRuntime.call.id);aiCallRuntime.call=r.call;const rr=r.call.result;status.innerHTML=`<b>Result: ${esc(rr.outcome)}</b><br>Risk score: <strong>${rr.riskScore}</strong><br>${esc(rr.reasons.join(' · ')||'No exception signals')}<br><br><b>${esc(rr.recommendation)}</b>${r.call.inspectionId?`<br>Inspection created automatically: ${esc(r.call.inspectionId)}`:''}`;renderCalls();};
  function renderCalls(){const c=w.querySelector('#calls');c.innerHTML='';if(!state.aiCalls.length){c.innerHTML='<div class="empty-state">No AI calls yet.</div>';return;}state.aiCalls.slice(0,10).forEach(x=>c.appendChild(el(`<div class="event-row"><div><b>${esc(x.instituteName)}</b><small>${esc(x.status)} · ${fmtDate(x.createdAt)}</small></div><span class="mini-tag ${x.result?.riskScore>=60?'risk-high':x.result?.riskScore>=30?'risk-watch':'risk-ok'}">${x.result?.riskScore??'—'}</span></div>`)));}
  renderCalls(); return w;
}

let liveCall=null;
function renderLiveCall(user){
 const w=el(`<div><div class="hero"><div><div class="eyebrow">SECURE LIVE VIDEO VERIFICATION</div><h2>Backend WebRTC call room</h2><p>Uses Socket.IO signaling + browser WebRTC. Open the same room in a second browser/device to demonstrate a real camera and microphone call without a third-party video SDK.</p></div><span class="ai-chip">WEBRTC + SOCKET.IO</span></div><div class="card"><div class="grid grid-2"><div><label>Room code</label><input id="room" value="dosje-demo-001"></div><div><label>Display name</label><input id="name" value="${esc(user.name)}"></div></div><div class="call-controls"><button class="btn accent" id="join">Join room</button><button class="btn secondary" id="leave">Leave</button><button class="btn" id="cam">Enable camera & mic</button></div></div><div class="call-grid"><div class="card"><h3>My camera</h3><div class="video-box"><video id="local" autoplay muted playsinline></video></div></div><div class="card"><h3>Remote participant</h3><div class="video-box"><video id="remote" autoplay playsinline></video></div></div></div><div class="card"><h3>Call event log</h3><div id="log" class="transcript"></div></div></div>`);
 function log(x){w.querySelector('#log').insertAdjacentHTML('afterbegin',`<div class="transcript-row">${esc(new Date().toLocaleTimeString())} — ${esc(x)}</div>`);}
 w.querySelector('#cam').onclick=async()=>{try{liveCall=liveCall||{};liveCall.stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});w.querySelector('#local').srcObject=liveCall.stream;log('Camera and microphone enabled.');}catch(e){showToast('Camera/mic permission: '+e.message,'error');}};
 w.querySelector('#join').onclick=async()=>{try{const room=w.querySelector('#room').value.trim();if(!room)return;const socket=window.io();liveCall={...(liveCall||{}),socket,room,pc:new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]})};if(!liveCall.stream)liveCall.stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});w.querySelector('#local').srcObject=liveCall.stream;liveCall.stream.getTracks().forEach(t=>liveCall.pc.addTrack(t,liveCall.stream));liveCall.pc.ontrack=e=>w.querySelector('#remote').srcObject=e.streams[0];liveCall.pc.onicecandidate=e=>{if(e.candidate)socket.emit('ice-candidate',{room,candidate:e.candidate});};socket.on('peer-joined',async()=>{log('Peer joined. Sending offer.');const offer=await liveCall.pc.createOffer();await liveCall.pc.setLocalDescription(offer);socket.emit('webrtc-offer',{room,offer});});socket.on('webrtc-offer',async({offer})=>{log('Offer received. Sending answer.');await liveCall.pc.setRemoteDescription(offer);const ans=await liveCall.pc.createAnswer();await liveCall.pc.setLocalDescription(ans);socket.emit('webrtc-answer',{room,answer:ans});});socket.on('webrtc-answer',async({answer})=>{log('Answer received.');await liveCall.pc.setRemoteDescription(answer);});socket.on('ice-candidate',async({candidate})=>{try{await liveCall.pc.addIceCandidate(candidate);}catch{}});socket.on('peer-left',()=>log('Remote participant left.'));socket.emit('join-call',room);log('Joined room '+room+'. Open this room on another device/browser.');}catch(e){showToast('Unable to start call: '+e.message,'error');}};
 w.querySelector('#leave').onclick=()=>{if(liveCall){liveCall.socket?.emit('leave-call',liveCall.room);liveCall.socket?.disconnect();liveCall.pc?.close();liveCall.stream?.getTracks().forEach(t=>t.stop());liveCall=null;w.querySelector('#local').srcObject=null;w.querySelector('#remote').srcObject=null;log('Call ended.');}};
 const history=el(`<div class="card"><div class="section-head"><h3>📚 Sample verification call database</h3><span class="badge-pill badge-online">DEMO DATA</span></div><div id="callHistory"></div></div>`);
 const hc=history.querySelector('#callHistory');
 const calls=state.aiCalls||[];
 if(!calls.length) hc.innerHTML='<div class="empty-state">No sample calls yet. Run npm run seed once.</div>';
 calls.slice(0,8).forEach(x=>hc.appendChild(el(`<div class="event-row"><div><b>${esc(x.instituteName||'Institute')}</b><small>${esc(x.status||'completed')} · Duration: ${esc(x.duration||'—')} · ${fmtDate(x.createdAt)}</small><div class="muted">${esc(x.summary||x.result?.recommendation||'AI verification record')}</div></div><span class="mini-tag ${x.result?.riskScore>=60?'risk-high':x.result?.riskScore>=30?'risk-watch':'risk-ok'}">Risk ${x.result?.riskScore??'—'}</span></div>`)));
 if(history && !w.querySelector('#callHistory')) w.appendChild(history);
 return w;
}

function renderFieldOps(user){
 const w=el(`<div><div class="hero"><div><div class="eyebrow">SMART FIELD INSPECTION OPERATIONS</div><h2>Forms · GPS · QR · signature · photo · workflows</h2><p>Mobile-first field collection with conditional logic. Exceptions are evaluated immediately and recorded in the backend.</p></div><span class="ai-chip">REAL-TIME WORKFLOW</span></div><div class="card"><h3>New field inspection</h3><form id="fieldForm"><div class="grid grid-3"><div><label>Institute</label><select id="fi">${state.institutes.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><div><label>Attendance</label><input id="att" type="number" min="0" placeholder="e.g. 24"></div><div><label>Temperature / mission metric</label><input id="temp" type="number" placeholder="e.g. 38"></div></div><label>QR / barcode</label><div class="grid grid-2"><input id="qr" placeholder="Scan or enter asset/attendance code"><button type="button" class="btn secondary" id="scanQr">▦ Scan QR / barcode</button></div><label>Notes</label><textarea id="notes" placeholder="Inspection observations..."></textarea><label>Photo evidence</label><input id="photo" type="file" accept="image/*" capture="environment"><label>Signature</label><canvas id="sig" class="signature-pad" width="700" height="150"></canvas><div class="call-controls"><button type="button" class="btn secondary" id="clearSig">Clear signature</button><button class="btn accent">Submit field inspection</button></div></form><div id="fieldResult"></div></div><div class="grid grid-2"><div class="card"><h3>Dispatch & scheduling</h3><form id="jobForm"><label>Job title</label><input id="jt" value="Surprise field inspection"><label>Institute</label><select id="ji">${state.institutes.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select><label>Scheduled for</label><input id="js" type="datetime-local"><button class="btn">Dispatch job</button></form><div id="jobs"></div></div><div class="card"><h3>Exception workflow history</h3><div id="subs"></div></div></div></div>`);
 const c=w.querySelector('#sig'),ctx=c.getContext('2d');let drawing=false,hasSig=false;const pos=e=>{const r=c.getBoundingClientRect();return {x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);};c.onpointermove=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();hasSig=true;};c.onpointerup=()=>drawing=false;c.onpointerleave=()=>drawing=false;
 w.querySelector('#clearSig').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);hasSig=false;};
 w.querySelector('#scanQr').onclick=async()=>{if('BarcodeDetector' in window){try{const d=new BarcodeDetector({formats:['qr_code','code_128','ean_13']});const file=w.querySelector('#photo').files[0];if(!file)return showToast('Choose a camera/photo first, then scan.','error');const bmp=await createImageBitmap(file);const codes=await d.detect(bmp);if(codes[0]){w.querySelector('#qr').value=codes[0].rawValue;showToast('Code scanned','success');}else showToast('No barcode detected; enter it manually','error');}catch(e){showToast('Scanner unavailable; enter code manually','error');}}else showToast('Browser barcode API unavailable; enter code manually','error');};
 w.querySelector('#fieldForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData();fd.append('instituteId',w.querySelector('#fi').value);fd.append('attendance',w.querySelector('#att').value);fd.append('temperature',w.querySelector('#temp').value);fd.append('qrCode',w.querySelector('#qr').value);fd.append('notes',w.querySelector('#notes').value);fd.append('signature',hasSig?c.toDataURL('image/png'):'');const f=w.querySelector('#photo').files[0];if(f)fd.append('photo',f);if(navigator.geolocation)await new Promise(resolve=>navigator.geolocation.getCurrentPosition(async p=>{fd.append('lat',p.coords.latitude);fd.append('lng',p.coords.longitude);resolve();},()=>resolve(),{enableHighAccuracy:true,timeout:6000}));try{const r=await api.submitFieldInspection(fd);const x=r.submission;w.querySelector('#fieldResult').innerHTML=`<div class="${x.exceptions.length?'error-box':'success-box'}"><b>${x.exceptions.length?'⚠ Workflow exceptions generated':'✅ Field inspection accepted'}</b><br>${x.exceptions.length?x.exceptions.join(' · '):'All required mission fields passed.'}<br>Captured at ${fmtDate(x.capturedAt)}</div>`;state.fieldSubmissions.unshift(x);renderFieldLists(w);}catch(e){showToast(e.message,'error');}};
 w.querySelector('#jobForm').onsubmit=async e=>{e.preventDefault();try{const r=await api.createFieldJob({title:w.querySelector('#jt').value,instituteId:w.querySelector('#ji').value,scheduledFor:w.querySelector('#js').value});state.fieldJobs.unshift(r.job);renderFieldLists(w);showToast('Job dispatched','success');}catch(e){showToast(e.message,'error');}};
 function renderFieldLists(root){const j=root.querySelector('#jobs');j.innerHTML='';state.fieldJobs.slice(0,8).forEach(x=>j.appendChild(el(`<div class="event-row"><div><b>${esc(x.title)}</b><small>${esc(x.instituteName)} → ${esc(x.inspectorName)}</small></div><span class="mini-tag">${esc(x.status)}</span></div>`)));const s=root.querySelector('#subs');s.innerHTML='';state.fieldSubmissions.slice(0,8).forEach(x=>s.appendChild(el(`<div class="event-row"><div><b>${esc(x.instituteName)}</b><small>${fmtDate(x.capturedAt)} · ${esc(x.submittedBy)}</small></div><span class="mini-tag ${x.exceptions?.length?'risk-high':'risk-ok'}">${x.exceptions?.length||0} exceptions</span></div>`)));}
 renderFieldLists(w);return w;
}
